function HitTestSettingsPopover({
  value,
  onChange,
}: {
  value: HitTestSettings;
  onChange: (value: HitTestSettings) => void;
}) {
  const t = useKnowledgeBaseComponentTranslate();
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(value);
  const [scoreText, setScoreText] = useState(() => value.score.toFixed(3));

  useEffect(() => {
    if (open) {
      setDraft(value);
      setScoreText(value.score.toFixed(3));
    }
  }, [open, value]);

  const save = () => {
    const score = Number(scoreText);
    if (!Number.isFinite(score)) return;
    onChange({
      topK: Math.max(1, Math.min(1000, Math.round(draft.topK))),
      score: Math.max(0, Math.min(1, score)),
    });
    setOpen(false);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <Button variant='outline' size='sm'>
            <Settings2 aria-hidden='true' />
            {t('Settings')}
          </Button>
        }
      />
      <PopoverContent align='end' className='w-64'>
        <form
          className='grid gap-3'
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <label className='grid gap-1.5 text-sm font-medium'>
            {t('Top K')}
            <Input
              type='number'
              min={1}
              max={1000}
              value={draft.topK}
              onChange={(event) =>
                setDraft((current) => ({
                  ...current,
                  topK: Number(event.target.value),
                }))
              }
            />
          </label>
          <label className='grid gap-1.5 text-sm font-medium'>
            {t('Score')}
            <Input
              type='number'
              min={0}
              max={1}
              step={0.1}
              required
              value={scoreText}
              onChange={(event) => setScoreText(event.target.value)}
            />
          </label>
          <div className='flex justify-end gap-2'>
            <Button
              type='button'
              variant='outline'
              size='sm'
              onClick={() => setOpen(false)}
            >
              {t('Cancel')}
            </Button>
            <Button type='submit' size='sm'>
              {t('Save')}
            </Button>
          </div>
        </form>
      </PopoverContent>
    </Popover>
  );
}

